import std.io

pub type AppError = Failed(String)

record Big { a: Int64, b: Int64, c: Int64, d: Int64 }

let g: Big = Big { a: 1, b: 2, c: 3, d: 4 }

fn churn() -> Int64 {
    var i: Int64 = 0
    while i < 80000 {
        let xs: List<Int64> = []
        let z: Int64 = i
        i = z + 1
    }
    return i
}

pub fn main() effect io -> Result<(), AppError> {
    let n = churn()
    let probe = Big { a: 9, b: 9, c: 9, d: 9 }
    io.println("${g.a} ${probe.a} ${n}")
    return Ok(())
}
